/**
 * Definition for singly-linked list.
 * class ListNode {
 *     val: number
 *     next: ListNode | null
 * }
 */
// 快慢指針找中點 → 反轉後半段 → 與前半段逐一比較
// 時間複雜度: O(n)，空間複雜度: O(1)
function isPalindrome(head) {
    let slow = head, fast = head;
    while (fast && fast.next) {
        slow = slow.next;
        fast = fast.next.next;
    }
    let prev = null; // 反轉後半段
    while (slow) {
        const next = slow.next;
        slow.next = prev;
        prev = slow;
        slow = next;
    }
    let a = head, b = prev;
    while (b) {
        if (a.val !== b.val)
            return false;
        a = a.next;
        b = b.next;
    }
    return true;
}

